/// are no attributes (SQS omits `MD5OfMessageAttributes` then).
pub fn md5_of_message_attributes(
    attributes: &BTreeMap<String, MessageAttributeValue>,
) -> Option<String> {
    md5_of_attribute_encoding(attributes)
}

