// SPDX-License-Identifier: CC0-1.0

//! Engine state for the com-amazonaws-sqs-amazonsqs service.
//!
//! The queue is this service's primary resource: `CreateQueue` allocates one,
//! `GetQueueUrl` resolves it by name, `GetQueueAttributes` reports it,
//! `SetQueueAttributes` changes it and `DeleteQueue` removes it, all against the SAME
//! [`Queue`] record in [`ComAmazonawsSqsAmazonsqsState::queues`], so a create is
//! observable by every later read and an attribute change by every later report.
//!
//! # One namespace per region
//!
//! two of those series with nobody calling.
//!
//! Everything a caller can make this in-memory store hold is bounded — see the
//! "Store bounds" section — and a bound is REFUSED rather than enforced by eviction,
//! because dropping a message a client was told had been accepted would lose it.

use std::collections::{BTreeMap, BTreeSet, HashMap, VecDeque};
use std::time::{Duration, SystemTime};

pub mod encryption;
/// The data key a queue on a customer managed KMS key seals its messages under: where it
/// comes from, how long it is reused before this service calls KMS again, and what the
/// account's audit record says about each of those calls.
pub mod data_keys;
pub use wording::*;
pub use clock::*;
pub use attribute_catalog::*;
pub use data_keys::{MessageDataKey, QueueDataKey};

use crate::ops::types::{
    InvalidAddress, InvalidAttributeName, InvalidAttributeValue, ListMessageMoveTasksResultEntry,
    MessageAttributeValue, MessageSystemAttributeValue, QueueDoesNotExist, ReceiptHandleIsInvalid,
    ResourceNotFoundException, UnsupportedOperation,
    MESSAGE_SYSTEM_ATTRIBUTE_NAME_FOR_SENDS_VALUES, QUEUE_ATTRIBUTE_NAME_VALUES,
};

/// Whether the policies in force let a request act on the queue it addresses — the gate
/// every operation that acts on a queue runs before it reports or changes anything — and
/// what a `Policy` attribute value has to look like to be stored at all.
pub mod authorization;
/// MD5 and SHA-256 digests of a message, and the byte count of its attribute maps.
mod digest;
/// The catalogue of queue attributes: their names, kinds and documented bounds.
mod attribute_catalog;
/// Epoch renderings and overflow-safe arithmetic on request-derived spans.
mod clock;
/// The fixed wording of this service's refusals.
mod wording;
/// How a queue is addressed: its key, ARN and url, and the reading of an ARN or url a request supplies.
mod addressing;
/// What the attributes a request supplies have to look like, and the refusals for each fault.
mod attribute_validation;
/// The bounds and wording shared by the batch operations.
mod batch;
/// The ceilings this in-memory store holds every caller-controlled collection to.
mod bounds;
/// The receipt handle a receive mints: its form, its provenance and its refusals.
mod receipt_handle;
/// What `CreateQueue` accepts: the queue name and the repeat of an existing queue's creation.
mod queue_creation;
/// Cost allocation tag bounds and refusals.
mod tags;
/// Page sizes, the `NextToken` cursor and the wording of a refused `MaxResults`.
mod pagination;
/// The message movement task record and the rules `StartMessageMoveTask` is held to.
mod message_move_task;
/// What a message attribute a send supplies has to look like, name and typed value alike.
mod message_attributes;
/// The bounds a queue policy is held to, and the wording of every refusal a grant or a
/// revoke answers with.
mod permissions;
/// The `AWS/SQS` series a queue publishes about itself: the backlog gauges it is sampled into
