import re
# 1. macro next to KeyRefusal
p='src/state/encryption.rs'
s=open(p).read()
anchor="pub enum KeyRefusal {"
i=s.index(anchor)
# end of the enum
j=s.index('\n}\n',i)+3
macro='''
/// Defines `fn kms_refusal(KeyRefusal) -> $error` for one operation: each class of refusal
/// becomes that operation's own `Kms*` modelled variant, carrying KMS's message.
///
/// A macro because every operation generates its own error enum, and no trait spans them.
/// `$modeled` is that operation's `...ErrorModeled` enum, which has to be in scope where
/// the macro is invoked.
macro_rules! kms_refusal_fn {
    ($(#[$attribute:meta])* $error:ty, $modeled:ident) => {
        $(#[$attribute])*
        fn kms_refusal(refusal: $crate::state::encryption::KeyRefusal) -> $error {
            use $crate::ops::types::{
                KmsAccessDenied, KmsDisabled, KmsInvalidKeyUsage, KmsInvalidState, KmsNotFound,
            };
            use $crate::state::encryption::KeyRefusal;
            match refusal {
                KeyRefusal::NotFound(message) => $modeled::KmsNotFound(KmsNotFound {
                    message: Some(message),
                }),
                KeyRefusal::Disabled(message) => $modeled::KmsDisabled(KmsDisabled {
                    message: Some(message),
                }),
                KeyRefusal::InvalidState(message) => $modeled::KmsInvalidState(KmsInvalidState {
                    message: Some(message),
                }),
                KeyRefusal::InvalidKeyUsage(message) => {
                    $modeled::KmsInvalidKeyUsage(KmsInvalidKeyUsage {
                        message: Some(message),
                    })
                }
                KeyRefusal::AccessDenied(message) => $modeled::KmsAccessDenied(KmsAccessDenied {
                    message: Some(message),
                }),
            }
            .into()
        }
    };
}
pub(crate) use kms_refusal_fn;
